final class Document {                     // the Whole
    private var parts: [Paragraph] = []    // owned parts: deinit cascades over ARC
    private let backing: FileHandle
    init(path: String) throws { backing = try FileHandle(forWritingTo: URL(fileURLWithPath: path)) }
    func add(_ text: String) -> Paragraph {
        let p = Paragraph(text, owner: self); parts.append(p); return p
    }
    deinit { for p in parts { p.close() }; try? backing.close() }   // parts, then resources
}

