struct Document {                                  // the Whole as a value type
    private(set) var parts: [Paragraph] = []       // copied with the document
    mutating func add(_ text: String) { parts.append(Paragraph(text: text)) }
    var totalLength: Int { parts.reduce(0) { $0 + $1.text.count } }
    // no deinit: value types have no destructor; resources need a reference part
}
